export default ({ orders, previous }) => {
  const index = previous?.index ?? 0,
    results = previous?.results ?? [],
    order = orders[index] ?? {};
  return {
    index,
    results,
    order,
    more: index < orders.length,
    endpoint: "/orders/" + (order.id ?? "") + "/fulfillment_orders.json",
  };
};

