function prepareBCOrder(order, fulfillment, config) {
  const guid = /^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i;
  const id = (value) =>
    typeof value === "string"
      ? /^\d+$/.test(value)
        ? value
        : ""
      : Number.isSafeInteger(value) && value > 0
        ? String(value)
        : "";
  const orderId = id(order.id);
  const email = typeof order.customer?.email === "string" ? order.customer.email.trim() : "";
  if (
    !orderId ||
    order.financial_status !== "paid" ||
    !/^\S+@\S+\.\S+$/.test(email) ||
    !/^\d{4}-\d{2}-\d{2}T/.test(order.created_at ?? "") ||
    !/^[A-Z]{3}$/.test(order.currency ?? "") ||
    !Array.isArray(order.line_items) ||
    !order.line_items.length ||
    fulfillment?.statusCode !== 200 ||
    !Array.isArray(fulfillment.body?.fulfillment_orders)
  )
    throw Error("Order, customer, or fulfillment data is incomplete.");
  const assigned = new Map();
  const validLines = new Set(order.line_items.map((line) => id(line.id)));
  if (validLines.has("") || validLines.size !== order.line_items.length)
    throw Error("Shopify line IDs are missing or repeated.");
  for (const group of fulfillment.body.fulfillment_orders) {
    if (id(group.order_id) !== orderId || !Array.isArray(group.line_items))
      throw Error("Fulfillment belongs to a different Shopify order.");
    const location = id(group.assigned_location_id);
    for (const entry of group.line_items) {
      const lineId = id(entry.line_item_id);
      if (!validLines.has(lineId) || !location)
        throw Error("Fulfillment line or location is invalid.");
      const locations = assigned.get(lineId) ?? new Set();
      locations.add(location);
      assigned.set(lineId, locations);
    }
  }
  const money = (value) => {
    if (
      (typeof value !== "string" && typeof value !== "number") ||
      !/^-?\d+(?:\.\d{1,6})?$/.test(String(value)) ||
      Math.abs(Number(value)) > 1000000000
    )
      throw Error("Order amount is invalid.");
    return Number(value);
  };
  const makeLine = ({ sku, title, quantity, price }) => {
    if (typeof sku !== "string" || !sku.trim() || !Number.isSafeInteger(quantity) || quantity < 1)
      throw Error("A Shopify line is missing an item SKU or quantity.");
    return {
      lineObjectNumber: sku.trim(),
      lineType: "Item",
      quantity,
      unitPrice: money(price),
      ...(typeof title === "string" && title.length ? { description: title } : {}),
    };
  };
  const lines = order.line_items.map(makeLine);
  if (config.taxesAsLineItem)
    lines.push(makeLine({ sku: config.taxItemSku, quantity: 1, price: order.total_tax }));
  if (config.discountsAsLineItem)
    lines.push(
      makeLine({ sku: config.discountItemSku, quantity: 1, price: -money(order.total_discounts) }),
    );
  if (lines.length > 100) throw Error("Order has more than 100 Business Central lines.");
  const address = order.shipping_address ?? {};
  const postal = Object.fromEntries(
    Object.entries({
      addressLine1: address.address1,
      addressLine2: address.address2,
      city: address.city,
      state: address.province,
      country: address.country_code,
      postalCode: address.zip,
      phoneNumber: address.phone,
    }).filter(([, v]) => typeof v === "string" && v.trim()),
  );
  const displayName = [order.customer.first_name, order.customer.last_name]
    .filter((value) => typeof value === "string" && value.trim())
    .join(" ")
    .trim();
  const kind = order.source_name === "pos" ? "salesInvoices" : "salesOrders";
  const invoice = kind === "salesInvoices";
  const document = {
    externalDocumentNumber: orderId,
    currencyCode: order.currency,
    [invoice ? "invoiceDate" : "orderDate"]: order.created_at.slice(0, 10),
    ...Object.fromEntries(
      Object.entries({
        sellToAddressLine1: address.address1,
        sellToAddressLine2: address.address2,
        sellToCity: address.city,
        sellToState: address.province,
        sellToCountry: address.country_code,
        sellToPostCode: address.zip,
      }).filter(([, v]) => typeof v === "string" && v.trim()),
    ),
  };
  return {
    orderId,
    kind,
    lineKind: invoice ? "salesInvoiceLines" : "salesOrderLines",
    document,
    lines,
    email,
    customer: {
      displayName,
      type: "Person",
      email,
      taxLiable: true,
      currencyCode: order.currency,
      ...postal,
    },
    locationCount: assigned.size,
    phase: "findDocument",
    lineIndex: 0,
  };
}

function nextBCRequest(work, config) {
  const literal = (value) =>
    encodeURIComponent("'" + value.replace(/'/g, "''") + "'").replace(/'/g, "%27");
  const doc = "/" + work.kind;
  const documentUrl = doc + "(" + work.documentId + ")";
  const operations = {
    findDocument: () => ({
      method: "GET",
      path:
        doc +
        "?$top=2&$filter=" +
        encodeURIComponent("externalDocumentNumber eq ") +
        literal(work.orderId),
    }),
    findCustomer: () => ({
      method: "GET",
      path: "/customers?$top=2&$filter=" + encodeURIComponent("email eq ") + literal(work.email),
    }),
    createCustomer: () => ({ method: "POST", path: "/customers", body: work.customer }),
    createDocument: () => ({
      method: "POST",
      path: doc,
      body: { ...work.document, customerId: work.customerId },
    }),
    createLine: () => ({
      method: "POST",
      path: documentUrl + "/" + work.lineKind,
      body: work.lines[work.lineIndex],
    }),
    checkCompensation: () => ({ method: "GET", path: documentUrl }),
    deleteDocument: () => ({
      method: "DELETE",
      path: documentUrl,
      headers: { "If-Match": work.etag },
    }),
  };
  const { path, method, body, headers } = operations[work.phase]();
  return { url: config.bc + path, method, headers: headers ?? {}, ...(body ? { body } : {}) };
}

function acceptBCResponse(work, response) {
  const okId = (value) =>
    typeof value === "string" && /^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(value);
  const result = (status) => ({
    done: true,
    outcome: {
      orderId: work.orderId,
      kind: work.kind,
      status,
      stage: work.phase,
      fulfillmentLines: work.locationCount,
      ...(work.documentId ? { documentId: work.documentId } : {}),
    },
  });
  const next = (phase, fields = {}) => ({ done: false, work: { ...work, ...fields, phase } });
  const { statusCode, body } = response ?? {};
  const sameParent = (row) =>
    okId(row?.id) &&
    row.id === work.documentId &&
    row.externalDocumentNumber === work.orderId &&
    row.customerId === work.customerId;
  const exactEmail = (row) =>
    okId(row?.id) &&
    typeof row.email === "string" &&
    row.email.toLowerCase() === work.email.toLowerCase();
  const list = () =>
    statusCode === 200 &&
    Array.isArray(body?.value) &&
    body.value.length <= 1 &&
    !body["@odata.nextLink"]
      ? body.value
      : null;
  switch (work.phase) {
    case "findDocument": {
      const matches = list();
      if (!matches) return result("review_lookup");
      if (!matches.length) return next("findCustomer");
      return okId(matches[0]?.id) && matches[0].externalDocumentNumber === work.orderId
        ? result("already_exists")
        : result("review_lookup");
    }
    case "findCustomer": {
      const matches = list();
      if (!matches) return result("review_lookup");
      if (!matches.length)
        return work.customer.displayName ? next("createCustomer") : result("missing_customer_name");
      return exactEmail(matches[0])
        ? next("createDocument", { customerId: matches[0].id })
        : result("review_lookup");
    }
    case "createCustomer":
      return statusCode === 201 && exactEmail(body)
        ? next("createDocument", { customerId: body.id })
        : result("review_customer_create");
    case "createDocument":
      return statusCode === 201 &&
        okId(body?.id) &&
        body.customerId === work.customerId &&
        body.externalDocumentNumber === work.orderId
        ? next("createLine", { documentId: body.id })
        : result("review_document_create");
    case "createLine":
      if (statusCode === 201 && okId(body?.id) && body.documentId === work.documentId) {
        return work.lineIndex + 1 < work.lines.length
          ? next("createLine", { lineIndex: work.lineIndex + 1 })
          : result("created");
      }
      if (
        [400, 422].includes(statusCode) &&
        typeof body?.error?.code === "string" &&
        body.error.code
      )
        return next("checkCompensation");
      return result("review_line_create");
    case "checkCompensation": {
      const etag = body?.["@odata.etag"] ?? response?.headers?.etag;
      const draft = ["draft", "open"].includes(String(body?.status ?? "").toLowerCase());
      return statusCode === 200 &&
        sameParent(body) &&
        draft &&
        typeof etag === "string" &&
        /^(?:W\/)?"[^"\r\n]+"$/.test(etag)
        ? next("deleteDocument", { etag })
        : result("review_before_cleanup");
    }
    case "deleteDocument":
      return result(statusCode === 204 ? "rolled_back" : "review_cleanup");
    default:
      throw Error("Unexpected Business Central phase.");
  }
}

export default async (
  { config, order, index, results, clientId, clientSecret, ...fulfillment },
  context,
) => {
  const next = (outcome) => ({ previous: { index: index + 1, results: [...results, outcome] } });
  let work;
  try {
    work = prepareBCOrder(order, fulfillment, config);
  } catch {
    return next({ orderId: String(order.id), status: "invalid_order_or_fulfillment" });
  }
  const key = "shopify-bc-order:" + config.scope + "|" + work.orderId;
  const earlier = await context.state.get(key);
  if (earlier)
    return next({
      orderId: work.orderId,
      status: "already_reserved",
      previousStatus: earlier.status,
    });
  const tokenUrl = "https://login.microsoftonline.com/" + config.tenantId + "/oauth2/v2.0/token";
  let token;
  try {
    const form = {
      client_id: clientId,
      client_secret: clientSecret,
      scope: "https://api.businesscentral.dynamics.com/.default",
      grant_type: "client_credentials",
    };
    const auth = await context.fetch(tokenUrl, {
      method: "POST",
      redirect: "manual",
      headers: { "content-type": "application/x-www-form-urlencoded" },
      body: Object.entries(form)
        .map(([key, value]) => key + "=" + encodeURIComponent(value))
        .join("&"),
    });
    if (auth.status === 200) token = (await auth.json()).access_token;
  } catch {}
  if (typeof token !== "string" || !token)
    return next({ orderId: work.orderId, status: "review_credentials" });
  if (!(await context.state.insert(key, { status: "pending" })))
    return next({ orderId: work.orderId, status: "already_reserved" });
  let result;
  do {
    const request = nextBCRequest(work, config);
    let response;
    try {
      const received = await context.fetch(request.url, {
        method: request.method,
        redirect: "manual",
        headers: {
          ...request.headers,
          authorization: "Bearer " + token,
          accept: "application/json",
          ...(request.body ? { "content-type": "application/json" } : {}),
        },
        ...(request.body ? { body: JSON.stringify(request.body) } : {}),
      });
      const text = await received.text();
      response = {
        statusCode: received.status,
        headers: { etag: received.headers.get("etag") },
        body: text ? JSON.parse(text) : null,
      };
    } catch {}
    result = acceptBCResponse(work, response);
    work = result.work;
  } while (!result.done);
  await context.state.set(key, result.outcome);
  return next(result.outcome);
};

